def count_queen_arrangements(n):
    cols = set()
    diag_down = set()  # row - col identifies one diagonal direction
    diag_up = set()    # row + col identifies the other
    def place(row):
        if row == n:
            return 1
        total = 0
        for col in range(n):
            if col in cols or (row - col) in diag_down or (row + col) in diag_up:
                continue
            cols.add(col)                 # choose
            diag_down.add(row - col)
            diag_up.add(row + col)
            total += place(row + 1)       # explore
            cols.remove(col)              # un-choose
            diag_down.remove(row - col)
            diag_up.remove(row + col)
        return total
    return place(0)
